$badReturnTx=$scalar("SELECT COUNT(*) FROM purchase_return_items ri LEFT JOIN inventory_transactions t ON t.id=ri.inventory_transaction_id AND t.organization_id=ri.organization_id WHERE ri.organization_id=? AND (t.id IS NULL OR t.movement_type<>'supplier_return' OR t.quantity_delta>=0 OR ABS(ABS(t.quantity_delta)-ri.quantity_returned)>0.0005)",[$orgId]);
