$badPayStatus=$scalar("SELECT COUNT(*) FROM purchase_bills b WHERE b.organization_id=? AND b.status='active' AND ((b.paid_amount<=0.009 AND b.payment_status<>'unpaid') OR (b.paid_amount>0.009 AND b.paid_amount+0.009<GREATEST(0,b.total_amount-b.return_credit) AND b.payment_status<>'partial') OR (ABS(b.paid_amount-GREATEST(0,b.total_amount-b.return_credit))<=0.009 AND b.paid_amount>0.009 AND b.payment_status<>'paid') OR (b.paid_amount>GREATEST(0,b.total_amount-b.return_credit)+0.009 AND b.payment_status<>'credit'))",[$orgId]);
