$badPurchaseRaw=$scalar("SELECT COUNT(*) FROM (SELECT raw_source_id rid FROM purchase_orders WHERE organization_id=? AND raw_source_id IS NOT NULL UNION ALL SELECT raw_source_id FROM purchase_bills WHERE organization_id=? AND raw_source_id IS NOT NULL UNION ALL SELECT raw_source_id FROM purchase_receipts WHERE organization_id=? AND raw_source_id IS NOT NULL UNION ALL SELECT raw_source_id FROM purchase_payments WHERE organization_id=? AND raw_source_id IS NOT NULL UNION ALL SELECT raw_source_id FROM purchase_returns WHERE organization_id=? AND raw_source_id IS NOT NULL) z LEFT JOIN raw_source_records r ON r.id=z.rid LEFT JOIN data_sources ds ON ds.id=r.data_source_id WHERE r.id IS NULL OR ds.source_code<>'PURCHASES'",[$orgId,$orgId,$orgId,$orgId,$orgId]);
